import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        # Track interactions with each other agent: for each agent_id, store a dict
        # with 'coop' (times opponent cooperated) and 'def' (times opponent defected)
        # when this agent was the donor (i.e., we chose an action) and when we observed them
        # as a third party we store observations in 'obs_coop' and 'obs_def'
        self.partner_stats = {}
        # Third-party observations: for each agent, counts of cooperative and defective actions
        self.observed_stats = {}
        # Track this agent's own cooperation count and defection count (for reputation)
        self.own_coop = 0
        self.own_def = 0
        # Track total rounds played (decisions made)
        self.rounds_played = 0
        # Opponent history: last few actions of each opponent (for pattern detection)
        self.opp_history = {}
        # For a simple memory: last action we chose against each opponent
        self.last_action_against = {}
        # Learning rate for adjusting cooperativeness based on observed reputation
        self.base_coop_prob = 0.5
        # A small noise to avoid deterministic deadlock
        self.noise = 0.02

    def decide(self) -> bool:
        # Get opponent id
        opp = self._ctx_opponent_id
        if opp is None:
            # Shouldn't happen, but fallback to cooperate
            return True

        # Initialize stats if not present
        if opp not in self.partner_stats:
            self.partner_stats[opp] = {'coop': 0, 'def': 0}
        if opp not in self.observed_stats:
            self.observed_stats[opp] = {'coop': 0, 'def': 0}
        if opp not in self.opp_history:
            self.opp_history[opp] = []
        if opp not in self.last_action_against:
            self.last_action_against[opp] = None

        # Compute a score for this opponent based on direct experience and observed reputation
        direct_coop = self.partner_stats[opp]['coop']
        direct_def = self.partner_stats[opp]['def']
        obs_coop = self.observed_stats[opp]['coop']
        obs_def = self.observed_stats[opp]['def']

        # If we have no data, use base probability
        total_direct = direct_coop + direct_def
        total_obs = obs_coop + obs_def

        # Reputation score: observed cooperation rate
        if total_obs > 0:
            obs_rate = obs_coop / total_obs
        else:
            obs_rate = 0.5  # neutral

        # Direct experience: cooperation rate against us
        if total_direct > 0:
            direct_rate = direct_coop / total_direct
        else:
            direct_rate = 0.5

        # Combine: give more weight to direct experience if we have enough, else use observation
        if total_direct >= 3:
            combined_rate = 0.7 * direct_rate + 0.3 * obs_rate
        else:
            combined_rate = 0.3 * direct_rate + 0.7 * obs_rate

        # Adjust based on own reputation: if we've been cooperating a lot, maybe be more trusting
        # But keep it simple: use combined_rate as probability to cooperate
        prob = combined_rate

        # Add a slight random noise to avoid deterministic cycles
        prob = max(0.0, min(1.0, prob + random.uniform(-self.noise, self.noise)))

        # Decide
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update observed stats for both donor and recipient
        # For donor
        if donor_id not in self.observed_stats:
            self.observed_stats[donor_id] = {'coop': 0, 'def': 0}
        if donor_action == 'cooperate':
            self.observed_stats[donor_id]['coop'] += 1
        else:
            self.observed_stats[donor_id]['def'] += 1

        # For recipient
        if recipient_id not in self.observed_stats:
            self.observed_stats[recipient_id] = {'coop': 0, 'def': 0}
        if recipient_action == 'cooperate':
            self.observed_stats[recipient_id]['coop'] += 1
        else:
            self.observed_stats[recipient_id]['def'] += 1

        # If we are involved in this interaction, update our partner stats
        if donor_id == self.agent_id:
            # We are donor
            if recipient_id not in self.partner_stats:
                self.partner_stats[recipient_id] = {'coop': 0, 'def': 0}
            # Record what recipient did (our opponent's action)
            if recipient_action == 'cooperate':
                self.partner_stats[recipient_id]['coop'] += 1
            else:
                self.partner_stats[recipient_id]['def'] += 1
            # Update own action counts
            if donor_action == 'cooperate':
                self.own_coop += 1
            else:
                self.own_def += 1
            # Record our action against that opponent
            self.last_action_against[recipient_id] = donor_action
            # Add to opp_history
            if recipient_id not in self.opp_history:
                self.opp_history[recipient_id] = []
            self.opp_history[recipient_id].append(recipient_action)
            # Keep last 10 actions
            if len(self.opp_history[recipient_id]) > 10:
                self.opp_history[recipient_id].pop(0)
            self.rounds_played += 1
        elif recipient_id == self.agent_id:
            # We are recipient
            if donor_id not in self.partner_stats:
                self.partner_stats[donor_id] = {'coop': 0, 'def': 0}
            # Record what donor did (our opponent's action)
            if donor_action == 'cooperate':
                self.partner_stats[donor_id]['coop'] += 1
            else:
                self.partner_stats[donor_id]['def'] += 1
            # Update own action counts (we are recipient, we also chose an action)
            if recipient_action == 'cooperate':
                self.own_coop += 1
            else:
                self.own_def += 1
            # Record our action against that opponent
            self.last_action_against[donor_id] = recipient_action
            # Add to opp_history
            if donor_id not in self.opp_history:
                self.opp_history[donor_id] = []
            self.opp_history[donor_id].append(donor_action)
            # Keep last 10
            if len(self.opp_history[donor_id]) > 10:
                self.opp_history[donor_id].pop(0)
            self.rounds_played += 1
        # If we are third party, we already updated observed_stats above

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputations: dict agent_id -> score (0 to 100)
        self.reputation = {}
        # Track own history: list of (opponent_id, my_action, opp_action)
        self.my_history = []
        # Track observed interactions: list of (donor, recipient, donor_act, recip_act)
        self.observed = []
        # Track cooperation count per opponent for trust
        self.coop_count = {}
        self.total_count = {}
        # Track recent actions for volatility
        self.recent_actions = {}
        # Generation counter (approximate by rounds seen)
        self.round_count = 0
        # Initial reputation for unknown agents
        self.default_rep = 50.0

    def _get_rep(self, agent_id: int) -> float:
        return self.reputation.get(agent_id, self.default_rep)

    def _update_rep(self, agent_id: int, delta: float) -> None:
        current = self._get_rep(agent_id)
        new = max(0.0, min(100.0, current + delta))
        self.reputation[agent_id] = new

    def _observe_action(self, agent_id: int, action: str) -> None:
        # Track recent actions for volatility (last 10 actions per agent)
        if agent_id not in self.recent_actions:
            self.recent_actions[agent_id] = []
        self.recent_actions[agent_id].append(action)
        if len(self.recent_actions[agent_id]) > 10:
            self.recent_actions[agent_id].pop(0)

    def _volatility(self, agent_id: int) -> float:
        actions = self.recent_actions.get(agent_id, [])
        if len(actions) < 3:
            return 0.0
        # Count changes between consecutive actions
        changes = sum(1 for i in range(1, len(actions)) if actions[i] != actions[i-1])
        return changes / (len(actions) - 1)

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # default cooperate if no opponent

        # If we have history with this opponent, use tit-for-tat with forgiveness
        if opponent in self.total_count and self.total_count[opponent] > 0:
            coop_rate = self.coop_count.get(opponent, 0) / self.total_count[opponent]
            # If opponent cooperates often, cooperate; else defect
            if coop_rate >= 0.6:
                return True
            elif coop_rate <= 0.3:
                return False
            else:
                # Mixed: probabilistic based on reputation and volatility
                rep = self._get_rep(opponent)
                vol = self._volatility(opponent)
                p = 0.3 + 0.5 * (rep / 100) - 0.3 * vol
                return random.random() < p
        else:
            # No history: trust reputation
            rep = self._get_rep(opponent)
            if rep >= 70:
                return True
            elif rep <= 30:
                return False
            else:
                # Random with slight bias to cooperate
                return random.random() < 0.6

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Increment round counter roughly (each observation is one round)
        self.round_count += 1

        # Update recent actions for both agents
        self._observe_action(donor_id, donor_action)
        self._observe_action(recipient_id, recipient_action)

        # Update reputation based on actions
        # Cooperating increases reputation, defecting decreases
        if donor_action == 'cooperate':
            self._update_rep(donor_id, +2.0)
        else:
            self._update_rep(donor_id, -3.0)
        if recipient_action == 'cooperate':
            self._update_rep(recipient_id, +1.0)
        else:
            self._update_rep(recipient_id, -2.0)

        # If we are one of the participants, update our direct history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent and our action
            if donor_id == self.agent_id:
                opponent = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opponent = donor_id
                my_action = recipient_action
                opp_action = donor_action
            self.my_history.append((opponent, my_action, opp_action))
            # Update per-opponent stats
            if opponent not in self.total_count:
                self.total_count[opponent] = 0
                self.coop_count[opponent] = 0
            self.total_count[opponent] += 1
            if opp_action == 'cooperate':
                self.coop_count[opponent] += 1
        else:
            # Third-party observation: store for potential use
            self.observed.append((donor_id, recipient_id, donor_action, recipient_action))
            # Keep observed list bounded
            if len(self.observed) > 1000:
                self.observed = self.observed[-1000:]

        # Occasionally decay reputation to avoid runaway scores (every ~50 observations)
        if self.round_count % 50 == 0:
            for aid in list(self.reputation.keys()):
                if aid != self.agent_id:
                    # Slight decay toward default
                    self.reputation[aid] = self.reputation[aid] * 0.99 + self.default_rep * 0.01

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation/defection history per opponent
        self.opponent_history = {}  # opponent_id -> list of (my_action, their_action)
        # Track third-party observations: (donor, recipient) -> last actions
        self.observed_pairs = {}  # (donor, recipient) -> (donor_action, recipient_action)
        # Track own reputation: how often I cooperated vs defected
        self.coop_count = 0
        self.defect_count = 0
        # Track defection likelihood of each agent based on observations
        self.defect_rate = {}  # agent_id -> [coop_count, defect_count]
        # Current opponent set by framework
        self._ctx_opponent_id = None
        # Memory of recent interactions with each opponent (last 10)
        self.recent_interactions = {}  # opponent_id -> list of (my_action, their_action)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            # Should not happen; default cooperate
            return True

        # Get opponent's defection rate from observations
        if opponent in self.defect_rate:
            coop, defect = self.defect_rate[opponent]
            total = coop + defect
            if total > 0:
                defect_prob = defect / total
            else:
                defect_prob = 0.5
        else:
            defect_prob = 0.5  # uncertain

        # Check recent direct interactions
        recent = self.recent_interactions.get(opponent, [])
        if recent:
            # If opponent defected in last interaction, be more cautious
            last_their_action = recent[-1][1]
            if last_their_action == 'defect':
                defect_prob = min(defect_prob + 0.2, 1.0)
            else:
                defect_prob = max(defect_prob - 0.1, 0.0)

        # Tit-for-tat style: if opponent has defected more than cooperated in direct history
        direct_history = self.opponent_history.get(opponent, [])
        if direct_history:
            their_defects = sum(1 for _, theirs in direct_history if theirs == 'defect')
            their_coops = len(direct_history) - their_defects
            if their_defects > their_coops:
                defect_prob = min(defect_prob + 0.3, 1.0)
            elif their_coops > their_defects:
                defect_prob = max(defect_prob - 0.2, 0.0)

        # Randomness with a bias: cooperate if defect_prob < 0.5, defect otherwise
        # Use deterministic threshold with slight randomness to avoid predictability
        threshold = 0.5
        # Add small noise based on agent_id to diversify
        noise = (self.agent_id % 7) / 100.0 - 0.03
        adjusted = defect_prob + noise
        if adjusted < threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update defection rates for both participants
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.defect_rate:
                self.defect_rate[agent_id] = [0, 0]
            if action == 'cooperate':
                self.defect_rate[agent_id][0] += 1
            else:
                self.defect_rate[agent_id][1] += 1

        # If I am a participant, record direct interaction
        if donor_id == self.agent_id:
            # I am donor
            opponent = recipient_id
            my_action = donor_action
            their_action = recipient_action
            self._record_interaction(opponent, my_action, their_action)
        elif recipient_id == self.agent_id:
            # I am recipient
            opponent = donor_id
            my_action = recipient_action
            their_action = donor_action
            self._record_interaction(opponent, my_action, their_action)
        else:
            # Third-party observation: store in observed_pairs for potential reputation tracking
            key = (donor_id, recipient_id)
            self.observed_pairs[key] = (donor_action, recipient_action)

        # Update own counts
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1

    def _record_interaction(self, opponent, my_action, their_action):
        if opponent not in self.opponent_history:
            self.opponent_history[opponent] = []
        self.opponent_history[opponent].append((my_action, their_action))
        # Keep last 10 for recency
        if opponent not in self.recent_interactions:
            self.recent_interactions[opponent] = []
        self.recent_interactions[opponent].append((my_action, their_action))
        if len(self.recent_interactions[opponent]) > 10:
            self.recent_interactions[opponent].pop(0)

