        # as a third party we store observations in 'obs_coop' and 'obs_def'
        self.partner_stats = {}
        # Third-party observations: for each agent, counts of cooperative and defective actions
        self.observed_stats = {}
        # Track this agent's own cooperation count and defection count (for reputation)
        self.own_coop = 0
        self.own_def = 0
        # Track total rounds played (decisions made)
        self.rounds_played = 0
        # Opponent history: last few actions of each opponent (for pattern detection)
        self.opp_history = {}
        # For a simple memory: last action we chose against each opponent
        self.last_action_against = {}
        # Learning rate for adjusting cooperativeness based on observed reputation
        self.base_coop_prob = 0.5
        # A small noise to avoid deterministic deadlock
        self.noise = 0.02

    def decide(self) -> bool:
        # Get opponent id
        opp = self._ctx_opponent_id
        if opp is None:
            # Shouldn't happen, but fallback to cooperate
            return True

        # Initialize stats if not present
        if opp not in self.partner_stats:
            self.partner_stats[opp] = {'coop': 0, 'def': 0}
