class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_count = 0
        self.defect_count = 0
        self.total_interactions = 0
        self.opponent_history = {}  # opponent_id -> list of (my_action, their_action)
        self.reputation = {}  # agent_id -> estimated cooperativeness (0-1)
        self.generosity = 0.7  # base probability to cooperate if no info

        # Track recent actions for adaptation
        self.my_recent_actions = []

        # For calculating reciprocity: how often I cooperated after they cooperated
        self.coop_after_coop = 0
        self.coop_after_defect = 0
        self.opp_coop_total = 0
        self.opp_defect_total = 0

        # Initialize reputation for all agents (unknown initially)
        for i in range(15):
            self.reputation[i] = 0.5

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return True

        # Get opponent's reputation and history
        opp_rep = self.reputation.get(opponent_id, 0.5)
        history = self.opponent_history.get(opponent_id, [])

        # Base decision: cooperate if reputation is good, defect if bad
        if opp_rep > 0.6:
            base_coop = True
        elif opp_rep < 0.4:
            base_coop = False
        else:
            base_coop = random.random() < self.generosity

        # If we have history, use tit-for-tat style adaptation
        if history:
            last_opp_action = history[-1][1]
            if last_opp_action == 'cooperate':
                # More likely to cooperate if they cooperated last time
                if random.random() < 0.8:
                    return True
            else:
                # More likely to defect if they defected last time
                if random.random() < 0.7:
                    return False

        # Occasionally be generous even if opponent is bad, but not too often
        if not base_coop and opp_rep < 0.3:
            if random.random() < 0.15:
                return True

        return base_coop

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for observed interactions
        try:
            # Determine if donor cooperated
            if donor_action == 'cooperate':
                self.reputation[donor_id] = min(1.0, self.reputation.get(donor_id, 0.5) + 0.05)
            else:
                self.reputation[donor_id] = max(0.0, self.reputation.get(donor_id, 0.5) - 0.05)

            # Similarly for recipient
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = min(1.0, self.reputation.get(recipient_id, 0.5) + 0.05)
            else:
                self.reputation[recipient_id] = max(0.0, self.reputation.get(recipient_id, 0.5) - 0.05)
        except:
            pass

        # If this involves us, record our own interaction
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine our action and opponent action
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            # Store history
            if opp_id not in self.opponent_history:
                self.opponent_history[opp_id] = []
            self.opponent_history[opp_id].append((my_action, opp_action))
            if len(self.opponent_history[opp_id]) > 10:
                self.opponent_history[opp_id].pop(0)

            # Update counts
            if my_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
            self.total_interactions += 1

            # Track conditional cooperation
            if opp_action == 'cooperate':
                self.opp_coop_total += 1
                if my_action == 'cooperate':
                    self.coop_after_coop += 1
            else:
                self.opp_defect_total += 1
                if my_action == 'cooperate':
                    self.coop_after_defect += 1

            self.my_recent_actions.append(my_action)
            if len(self.my_recent_actions) > 20:
                self.my_recent_actions.pop(0)

            # Adapt generosity based on overall cooperation level
            if self.opp_coop_total > 0:
                coop_rate = self.coop_after_coop / self.opp_coop_total
                if coop_rate < 0.5:
                    self.generosity = max(0.3, self.generosity - 0.01)
                elif coop_rate > 0.8:
                    self.generosity = min(0.9, self.generosity + 0.01)

