import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores: key = other agent id, value = our belief about their cooperativeness
        self.reputation = {}
        # Track direct interactions: key = (other_id, my_action, their_action), value = count
        self.interaction_history = {}
        # Track observations of third-party interactions: key = (donor_id, recipient_id, donor_action, recipient_action)
        self.observation_history = {}
        # Track how often each agent has been observed to cooperate/defect as donor/recipient
        self.coop_count = {}
        self.defect_count = {}
        self.round_number = 0
        # Personal memory of recent outcomes to adjust own strategy
        self.recent_results = []  # list of (my_action, opponent_action)

    def decide(self) -> bool:
        # Get opponent id
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            # Should not happen, but safe default
            return True

        # Initialize reputation for opponent if not seen
        if opponent_id not in self.reputation:
            self.reputation[opponent_id] = 0.0

        # If we have no info, default to cooperate
        if opponent_id not in self.coop_count and opponent_id not in self.defect_count:
            return True

        # Compute reputation from observations (third-party + direct)
        # Use a simple Bayesian-like estimate: p = (coop + 1) / (coop + defect + 2)
        coop = self.coop_count.get(opponent_id, 0)
        defect = self.defect_count.get(opponent_id, 0)
        if coop + defect == 0:
            return True

        prob_coop = (coop + 1) / (coop + defect + 2)
        # Tit-for-tat with forgiveness: if they cooperated more than 50% of time, cooperate
        # but also consider our own recent outcomes to avoid being exploited
        threshold = 0.5
        if prob_coop >= threshold:
            return True
        else:
            # If they are below threshold, maybe defect to punish
            # But occasionally forgive (1 in 10 chance) to allow recovery
            if random.random() < 0.1:
                return True
            else:
                return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update observation history
        key = (donor_id, recipient_id, donor_action, recipient_action)
        self.observation_history[key] = self.observation_history.get(key, 0) + 1

        # Update counts for donor and recipient
        # Donor's action: if donor is not self (but even if self, we can record for learning)
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
            else:
                self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        # Recipient's action
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
            else:
                self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

        # Track direct interactions if we are involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine my action and opponent action
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id
            # Record interaction
            self.interaction_history[(opp_id, my_action, opp_action)] = self.interaction_history.get((opp_id, my_action, opp_action), 0) + 1
            # Also store recent results for own strategy adjustment
            self.recent_results.append((my_action, opp_action))
            if len(self.recent_results) > 20:
                self.recent_results.pop(0)

            # Update reputation based on direct experience (more weight)
            # Simple: adjust reputation based on opponent's action
            if opp_action == 'cooperate':
                self.reputation[opp_id] = self.reputation.get(opp_id, 0.0) + 0.1
            else:
                self.reputation[opp_id] = self.reputation.get(opp_id, 0.0) - 0.1
            # Clamp to [-1, 1]
            self.reputation[opp_id] = max(-1.0, min(1.0, self.reputation[opp_id]))

        # Update counts for self as well to keep track of our own behavior (optional)
        if donor_id == self.agent_id:
            # Our own action as donor
            pass  # Not needed for decision, but could be used
        if recipient_id == self.agent_id:
            pass

