class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = {}
        self.own_recent_actions = []
        self.cooperation_count = 0
        self.total_observations = 0
        self._ctx_opponent_id = None
        self.generation = 0
        self.round_in_generation = 0
        self.max_history = 20
        self.pair_counts = {}
        self.min_obs_for_trust = 4

    def _update_round_counters(self):
        pass

    def decide(self) -> bool:
        self.round_in_generation += 1
        if self.round_in_generation > 30:
            self.generation += 1
            self.round_in_generation = 1

        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        self.pair_counts[opponent] = self.pair_counts.get(opponent, 0) + 1

        history = self.interaction_history.get(opponent, [])
        if len(history) == 0:
            rep = self.reputation.get(opponent, 0.5)
            return rep >= 0.4
        else:
            recent = history[-min(5, len(history)):]
            coop_count = sum(1 for (a, b) in recent if b == 'cooperate')
            coop_ratio = coop_count / len(recent)
            rep = self.reputation.get(opponent, 0.5)
            if coop_ratio >= 0.5 and rep > 0.3:
                return True
            else:
                return False

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        self.total_observations += 1

        if donor_id == self.agent_id:
            self.own_recent_actions.append(donor_action)
            if len(self.own_recent_actions) > self.max_history:
                self.own_recent_actions.pop(0)
            if donor_action == 'cooperate':
                self.cooperation_count += 1
        elif recipient_id == self.agent_id:
            self.own_recent_actions.append(recipient_action)
            if len(self.own_recent_actions) > self.max_history:
                self.own_recent_actions.pop(0)
            if recipient_action == 'cooperate':
                self.cooperation_count += 1

        if donor_id != self.agent_id:
            old_rep = self.reputation.get(donor_id, 0.5)
            if donor_action == 'cooperate':
                new_rep = old_rep + 0.1 * (1.0 - old_rep)
            else:
                new_rep = old_rep - 0.1 * old_rep
            new_rep = max(0.0, min(1.0, new_rep))
            self.reputation[donor_id] = new_rep

        if recipient_id != self.agent_id:
            old_rep = self.reputation.get(recipient_id, 0.5)
            if recipient_action == 'cooperate':
                new_rep = old_rep + 0.1 * (1.0 - old_rep)
            else:
                new_rep = old_rep - 0.1 * old_rep
            new_rep = max(0.0, min(1.0, new_rep))
            self.reputation[recipient_id] = new_rep

        if donor_id == self.agent_id:
            opponent = recipient_id
            my_action = donor_action
            their_action = recipient_action
            if opponent not in self.interaction_history:
                self.interaction_history[opponent] = []
            self.interaction_history[opponent].append((my_action, their_action))
            if len(self.interaction_history[opponent]) > self.max_history:
                self.interaction_history[opponent].pop(0)
        elif recipient_id == self.agent_id:
            opponent = donor_id
            my_action = recipient_action
            their_action = donor_action
            if opponent not in self.interaction_history:
                self.interaction_history[opponent] = []
            self.interaction_history[opponent].append((my_action, their_action))
            if len(self.interaction_history[opponent]) > self.max_history:
                self.interaction_history[opponent].pop(0)

