class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.generation = 0
        self.round = 0
        self.reputation = {i: 0.0 for i in range(15)}
        self.trust = {i: 0.0 for i in range(15)}
        self.coop_count = 0
        self.defect_count = 0
        self.observed_actions = []
        self.my_reputation_history = []
        self.opponent_coop_rate = {}
        self.opponent_actions = {i: [] for i in range(15)}
        self.recent_self_outcomes = []
        self.temperature = 1.0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Update temperature based on generation (explore more early)
        if self.round < 30:
            self.temperature = max(0.5, 1.0 - self.generation * 0.02)

        # Estimate opponent's cooperation probability
        opp_coop_prob = 0.5
        if opponent in self.opponent_coop_rate:
            opp_coop_prob = self.opponent_coop_rate[opponent]
        # Adjust based on reputation
        rep_factor = self.reputation.get(opponent, 0.0) / 10.0
        opp_coop_prob = 0.5 * opp_coop_prob + 0.5 * (0.5 + rep_factor)

        # My past cooperation rate
        total_actions = self.coop_count + self.defect_count
        my_coop_rate = self.coop_count / max(1, total_actions)

        # Noise term for exploration
        noise = random.gauss(0, 0.1 * self.temperature)

        # Strategy: cooperate if opponent likely cooperative and my reputation is decent
        threshold = 0.5 - 0.1 * (my_coop_rate - 0.5) + noise
        decide_coop = opp_coop_prob > threshold

        # Occasionally retaliate if opponent has been defecting often
        if opponent in self.opponent_actions and len(self.opponent_actions[opponent]) >= 3:
            recent = self.opponent_actions[opponent][-3:]
            if recent.count('defect') >= 2:
                decide_coop = False

        return decide_coop

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Track round and generation increments are handled externally, but we can infer from call patterns
        # Actually the framework calls decide before observe for each pair, so we can use a counter
        # We'll just increment a round counter when we see self as donor or recipient
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round += 1
            if self.round % 30 == 0:
                self.generation += 1
                self.round = 0
                self.my_reputation_history.append(self.reputation.get(self.agent_id, 0.0))
                # Decay reputation over generations
                for other in self.reputation:
                    self.reputation[other] *= 0.9

        # Update opponent action history
        if donor_id != self.agent_id:
            self.opponent_actions.setdefault(donor_id, []).append(donor_action)
            # Update cooperation rate
            actions = self.opponent_actions[donor_id]
            self.opponent_coop_rate[donor_id] = actions.count('cooperate') / len(actions)
        if recipient_id != self.agent_id:
            self.opponent_actions.setdefault(recipient_id, []).append(recipient_action)
            actions = self.opponent_actions[recipient_id]
            self.opponent_coop_rate[recipient_id] = actions.count('cooperate') / len(actions)

        # Update own stats
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1

        # Update reputation based on observed actions (third-party and self)
        # Cooperative behaviors increase reputation, defection decreases
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + 0.1
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) - 0.2
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + 0.1
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) - 0.2

        # Clamp reputation to reasonable range
        for k in self.reputation:
            self.reputation[k] = max(-5.0, min(5.0, self.reputation[k]))

        # Update trust: trust increases when others cooperate with us, decreases when they defect
        if donor_id == self.agent_id and recipient_id != self.agent_id:
            # We did something to someone else
            pass
        elif recipient_id == self.agent_id:
            # Someone acted towards us
            if donor_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0.0) + 0.1
            else:
                self.trust[donor_id] = self.trust.get(donor_id, 0.0) - 0.2

        # Store observed actions for potential pattern analysis
        self.observed_actions.append((donor_id, donor_action, recipient_id, recipient_action))
        if len(self.observed_actions) > 200:
            self.observed_actions.pop(0)

