    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round = 0
        self.generation = 0
        self.total_rounds = 0
        self._ctx_opponent_id = None
        # Reputation tracking: maps observed agent_id to (cooperate_count, defect_count)
        self.reputation = {}
        # Track own history with each opponent
        self.own_history = {}
        # Global cooperation rate estimate
        self.global_coop_count = 0
        self.global_total_obs = 0
        # My recent actions (True=cooperate)
        self.my_actions = []
        # Track whether I've seen this opponent before
        self.first_encounter = {}

    def _update_rep(self, agent_id, action):
        if agent_id not in self.reputation:
            self.reputation[agent_id] = [0, 0]
        if action == 'cooperate':
            self.reputation[agent_id][0] += 1
        else:
            self.reputation[agent_id][1] += 1

    def _get_rep_score(self, agent_id):
        if agent_id not in self.reputation:
            return 0.5
        coop, defect = self.reputation[agent_id]
        total = coop + defect
        if total == 0:
            return 0.5
        return coop / total

    def _get_my_rep_score(self):
        # My reputation as seen by others: use global cooperation rate as proxy
        if self.global_total_obs == 0:
            return 0.5
        return self.global_coop_count / self.global_total_obs

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        # Basic strategy: cooperate if opponent's reputation is decent
        # and we've had a cooperative interaction before, otherwise be cautious.
        opp_rep = self._get_rep_score(opp)
        # My own reputation matters for maintaining good standing
        my_rep = self._get_my_rep_score()
        # If I have history with this opponent, use it
        if opp in self.own_history:
            my_coop, my_def, their_coop, their_def = self.own_history[opp]
            total_inter = my_coop + my_def
            if total_inter > 0:
                their_coop_rate = their_coop / (their_coop + their_def)
                # Tit-for-tat-ish: cooperate if they cooperated recently or reputation good
                if their_coop_rate > 0.39:
                    return True
                else:
                    # If they defect often, defect
                    return False
        # First encounter: use reputation
        if opp_rep >= 0.5:
            # If global cooperation is high, be generous
            if my_rep >= 0.5:
                return True
            else:
                # If my reputation is low, I might need to cooperate to rebuild
                return True
        else:
            # If opponent has bad reputation, defect to avoid being exploited
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both observed agents
        self._update_rep(donor_id, donor_action)
        self._update_rep(recipient_id, recipient_action)
        # Update global stats
        self.global_total_obs += 2
        if donor_action == 'cooperate':
            self.global_coop_count += 1
        if recipient_action == 'cooperate':
            self.global_coop_count += 1

        # Track my own history if I'm involved
        if donor_id == self.agent_id:
            # I was donor
            opp = recipient_id
            if opp not in self.own_history:
                self.own_history[opp] = [0, 0, 0, 0]  # my_coop, my_def, their_coop, their_def
            if donor_action == 'cooperate':
                self.own_history[opp][0] += 1
            else:
                self.own_history[opp][1] += 1
            if recipient_action == 'cooperate':
                self.own_history[opp][2] += 1
            else:
                self.own_history[opp][3] += 1
        elif recipient_id == self.agent_id:
            # I was recipient
            opp = donor_id
            if opp not in self.own_history:
                self.own_history[opp] = [0, 0, 0, 0]
            if donor_action == 'cooperate':
                self.own_history[opp][2] += 1
            else:
                self.own_history[opp][3] += 1
            if recipient_action == 'cooperate':
                self.own_history[opp][0] += 1
            else:
                self.own_history[opp][1] += 1

