class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None

        # Reputation scores for all agents (including self)
        # Start neutral at 0, range roughly -1 to 1
        self.reputation = {}

        # Count of interactions observed per pair (donor, recipient)
        self.interaction_count = {}

        # Cooperation frequency per agent (weighted recency)
        self.coop_freq = {}
        self.defect_freq = {}

        # Trust in each agent based on their behavior
        self.trust = {}

        # For memory of own interactions
        self.my_interactions = []  # list of (opponent_id, my_action, opp_action)

        # Current round number (incremented by observe calls, reset per generation? 
        # We'll just count total observations)
        self.observation_count = 0

        # For a simple adaptive threshold
        self.coop_threshold = 0.5  # baseline

    def _normalize_id(self, agent_id):
        return agent_id

    def _update_reputation(self, agent_id, delta):
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.0
        self.reputation[agent_id] = max(-1.0, min(1.0, self.reputation[agent_id] + delta))

    def _update_freq(self, agent_id, action):
        if action == 'cooperate':
            if agent_id not in self.coop_freq:
                self.coop_freq[agent_id] = 0.0
                self.defect_freq[agent_id] = 0.0
            self.coop_freq[agent_id] += 1.0
        else:
            if agent_id not in self.defect_freq:
                self.defect_freq[agent_id] = 0.0
                self.coop_freq[agent_id] = 0.0
            self.defect_freq[agent_id] += 1.0

    def _get_coop_probability(self, agent_id):
        total = self.coop_freq.get(agent_id, 0) + self.defect_freq.get(agent_id, 0)
        if total == 0:
            return 0.5  # unknown
        return self.coop_freq[agent_id] / total

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        if opponent_id is None:
            return True  # fallback

        # If we have interacted before, use that info
        past_opponent_actions = [opp for (opp, my, theirs) in self.my_interactions if opp == opponent_id]
        if past_opponent_actions:
            coop_count = past_opponent_actions.count('cooperate')
            coop_ratio = coop_count / len(past_opponent_actions)
            # If opponent cooperated most of the time, cooperate; else defect
            return coop_ratio >= 0.5
        else:
            # Use reputation from observations
            opp_rep = self.reputation.get(opponent_id, 0.0)
            # Also consider their cooperation frequency
            opp_coop_freq = self._get_coop_probability(opponent_id)
            # Combine: if reputation positive or coop freq high, cooperate
            if opp_rep > 0.2 or opp_coop_freq > 0.6:
                return True
            elif opp_rep < -0.2 or opp_coop_freq < 0.4:
                return False
            else:
                # Uncertain: use a deterministic pattern based on agent id
                # cooperate if (my_id + round) even? But we don't have round.
                # Use observation_count as proxy
                return (self.agent_id + self.observation_count) % 3 != 0

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.observation_count += 1

        # Update counts
        pair = (donor_id, recipient_id)
        if pair not in self.interaction_count:
            self.interaction_count[pair] = 0
        self.interaction_count[pair] += 1

        # Update frequency
        self._update_freq(donor_id, donor_action)
        self._update_freq(recipient_id, recipient_action)

        # Update reputation based on actions
        # Cooperating with someone who cooperates: positive
        # Defecting when opponent cooperates: negative
        # Cooperating when opponent defects: negative (for being exploited)
        # Defecting when opponent defects: neutral or slightly positive (self-defense)

        # For donor
        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            self._update_reputation(donor_id, 0.1)
            self._update_reputation(recipient_id, 0.1)
        elif donor_action == 'cooperate' and recipient_action == 'defect':
            self._update_reputation(donor_id, -0.2)  # exploited
            self._update_reputation(recipient_id, -0.3)  # exploiter
        elif donor_action == 'defect' and recipient_action == 'cooperate':
            self._update_reputation(donor_id, -0.3)
            self._update_reputation(recipient_id, -0.2)
        elif donor_action == 'defect' and recipient_action == 'defect':
            self._update_reputation(donor_id, 0.05)  # mutual defection is reasonable
            self._update_reputation(recipient_id, 0.05)

        # Update trust: trust increases with mutual cooperation, decreases with being exploited
        if donor_id != recipient_id:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0) + 1
                self.trust[recipient_id] = self.trust.get(recipient_id, 0) + 1
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.trust[recipient_id] = self.trust.get(recipient_id, 0) - 2
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0) - 2

        # If this is our own interaction, record it
        if donor_id == self.agent_id:
            self.my_interactions.append((recipient_id, donor_action, recipient_action))
        elif recipient_id == self.agent_id:
            # If we are recipient, we also see it; but donor is the other
            # Actually we are recipient, so our action is recipient_action
            # But we need to store as (opponent, my_action, their_action)
            self.my_interactions.append((donor_id, recipient_action, donor_action))

        # Keep only last 50 interactions for memory
        if len(self.my_interactions) > 50:
            self.my_interactions = self.my_interactions[-50:]

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = []
        self.rounds_played = 0
        self.opponent_recent_actions = {}
        self.memory = 10
        self.coop_threshold = 0.0
        self.initial_rep = 0.0
        self.self_reputation = 0.0
        self.observation_counts = {}
        self.my_history = []
        self.generosity = 0.1
        self._ctx_opponent_id = None

    def _get_rep(self, agent_id: int) -> float:
        return self.reputation.get(agent_id, self.initial_rep)

    def _update_rep(self, agent_id: int, delta: float) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = self.initial_rep
        self.reputation[agent_id] = max(-1.0, min(1.0, self.reputation[agent_id] + delta))
        self.observation_counts[agent_id] = self.observation_counts.get(agent_id, 0) + 1

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True

        opp_id = self._ctx_opponent_id
        rep = self._get_rep(opp_id)

        if self.observation_counts.get(opp_id, 0) == 0:
            if self.rounds_played < 5:
                return True
            else:
                return random.random() > 0.3

        if rep > self.coop_threshold:
            return True
        elif rep < -0.2:
            return False
        else:
            recent_actions = self.opponent_recent_actions.get(opp_id, [])
            if recent_actions:
                coop_rate = sum(1 for a in recent_actions if a == 'cooperate') / len(recent_actions)
                if coop_rate > 0.6:
                    return True
                elif coop_rate < 0.4:
                    return False
                else:
                    return random.random() < (0.5 + self.generosity)
            else:
                return rep > 0.0

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        if donor_id == self.agent_id:
            self.self_reputation += 0.1 if donor_action == 'cooperate' else -0.1
            self.my_history.append((donor_id, recipient_id, donor_action))
        elif recipient_id == self.agent_id:
            self.self_reputation += 0.1 if recipient_action == 'cooperate' else -0.1
            self.my_history.append((donor_id, recipient_id, recipient_action))

        if donor_id != self.agent_id:
            delta = 0.2 if donor_action == 'cooperate' else -0.2
            self._update_rep(donor_id, delta)

        if recipient_id != self.agent_id:
            delta = 0.1 if recipient_action == 'cooperate' else -0.1
            self._update_rep(recipient_id, delta)

        if recipient_id != self.agent_id:
            if recipient_id not in self.opponent_recent_actions:
                self.opponent_recent_actions[recipient_id] = []
            self.opponent_recent_actions[recipient_id].append(recipient_action)
            if len(self.opponent_recent_actions[recipient_id]) > self.memory:
                self.opponent_recent_actions[recipient_id].pop(0)

        if donor_id != self.agent_id:
