import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = []
        self.rounds_played = 0
        self.opponent_recent_actions = {}
        self.memory = 10
        self.coop_threshold = 0.05
        self.initial_rep = 0.0
        self.self_reputation = 0.0
        self.observation_counts = {}
        self.my_history = []
        self.generosity = 0.1
        self._ctx_opponent_id = None

    def _get_rep(self, agent_id: int) -> float:
        return self.reputation.get(agent_id, self.initial_rep)

    def _update_rep(self, agent_id: int, delta: float) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = self.initial_rep
        self.reputation[agent_id] = max(-1.0, min(1.0, self.reputation[agent_id] + delta))
        self.observation_counts[agent_id] = self.observation_counts.get(agent_id, 0) + 1

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True

        opp_id = self._ctx_opponent_id
        rep = self._get_rep(opp_id)

        if self.observation_counts.get(opp_id, 0) == 0:
            if self.rounds_played < 5:
                return True
            else:
                return random.random() > 0.3

        if rep > self.coop_threshold:
            return True
        elif rep < -0.2:
            return False
        else:
            recent_actions = self.opponent_recent_actions.get(opp_id, [])
            if recent_actions:
                coop_rate = sum(1 for a in recent_actions if a == 'cooperate') / len(recent_actions)
                if coop_rate > 0.6:
                    return True
                elif coop_rate < 0.4:
                    return False
                else:
                    return random.random() < (0.5 + self.generosity)
            else:
                return rep > 0.0

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        if donor_id == self.agent_id:
            self.self_reputation += 0.1 if donor_action == 'cooperate' else -0.1
            self.my_history.append((donor_id, recipient_id, donor_action))
        elif recipient_id == self.agent_id:
            self.self_reputation += 0.1 if recipient_action == 'cooperate' else -0.1
            self.my_history.append((donor_id, recipient_id, recipient_action))

        if donor_id != self.agent_id:
            delta = 0.2 if donor_action == 'cooperate' else -0.2
            self._update_rep(donor_id, delta)

        if recipient_id != self.agent_id:
            delta = 0.1 if recipient_action == 'cooperate' else -0.1
            self._update_rep(recipient_id, delta)

        if recipient_id != self.agent_id:
            if recipient_id not in self.opponent_recent_actions:
                self.opponent_recent_actions[recipient_id] = []
            self.opponent_recent_actions[recipient_id].append(recipient_action)
            if len(self.opponent_recent_actions[recipient_id]) > self.memory:
                self.opponent_recent_actions[recipient_id].pop(0)

        if donor_id != self.agent_id:
            if donor_id not in self.opponent_recent_actions:
                self.opponent_recent_actions[donor_id] = []
            self.opponent_recent_actions[donor_id].append(donor_action)
            if len(self.opponent_recent_actions[donor_id]) > self.memory:
                self.opponent_recent_actions[donor_id].pop(0)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.rounds_played += 1

        if self.rounds_played % 10 == 0:
            if self.self_reputation < -0.5:
                self.generosity = max(0.0, self.generosity - 0.02)
            elif self.self_reputation > 0.5:
                self.generosity = min(0.3, self.generosity + 0.02)

