import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.self_coop_count = 0
        self.self_total = 0
        self.history = {}
        self.base_cooperation = 0.61
        self.last_own_action = None
        self.consecutive_defects = 0
        self.consecutive_coops = 0

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        prob = self.base_cooperation

        opp_rep = self.reputation.get(opponent_id, 0.5)
        prob += (opp_rep - 0.5) * 0.6

        hist = self.history.get(opponent_id, [])
        if hist:
            defections = sum(1 for coop in hist if not coop)
            if defections > 0:
                prob -= min(0.3, defections * 0.1)
            else:
                prob += min(0.2, len(hist) * 0.05)

        if self.consecutive_defects >= 2:
            prob += 0.2
        elif self.consecutive_coops >= 3:
            prob -= 0.1

        prob = max(0.0, min(1.0, prob))

        return random.random() < prob

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        for aid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if aid != self.agent_id:
                current = self.reputation.get(aid, 0.5)
                new_val = current * 0.9 + (1.0 if action == 'cooperate' else 0.0) * 0.1
                self.reputation[aid] = new_val

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            opp_id = recipient_id if donor_id == self.agent_id else donor_id

            self.self_total += 1
            if my_action == 'cooperate':
                self.self_coop_count += 1
                self.consecutive_coops += 1
                self.consecutive_defects = 0
            else:
                self.consecutive_coops = 0
                self.consecutive_defects += 1

            hist = self.history.setdefault(opp_id, [])
            hist.append(opp_action == 'cooperate')
            if len(hist) > 5:
                hist.pop(0)

