class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> float reputation score
        self.cooperation_counts = {}  # agent_id -> (coops, defections)
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.round_num = 0
        self.last_opponent = None
        self.my_last_action = None
        self.opponent_last_action = None

    def decide(self) -> bool:
        # Update round counter if new round (detect via opponent change)
        if self._ctx_opponent_id != self.last_opponent:
            self.round_num += 1
            self.last_opponent = self._ctx_opponent_id

        opp = self._ctx_opponent_id

        # Initialize reputation for unseen agents
        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.cooperation_counts:
            self.cooperation_counts[opp] = (0, 0)

        # Get opponent's cooperation rate
        coops, defs = self.cooperation_counts[opp]
        total = coops + defs
        if total == 0:
            coop_rate = 0.5
        else:
            coop_rate = coops / total

        # Basic tit-for-tat with forgiveness and reputation adjustment
        # Start cooperating, then mirror opponent's last action with some leniency
        if self.round_num <= 1:
            action = True
        else:
            # If opponent defected last time, defect with probability based on their reputation
            if self.opponent_last_action == 'defect':
                # Forgive if opponent has high reputation and high cooperation rate
                if self.reputation[opp] > 0.7 and coop_rate > 0.6:
                    action = True
                else:
                    # Defect with probability proportional to how bad their reputation is
                    defect_prob = 1.0 - self.reputation[opp]
                    action = random.random() > defect_prob
            else:
                # If opponent cooperated, cooperate with high probability
                action = random.random() < (0.9 + 0.1 * self.reputation[opp])

        # Store action for next round
        self.my_last_action = action
        return action

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for donor and recipient
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
