import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> reputation value
        self.my_reputation = 0.0
        self.interactions = {}  # agent_id -> list of (my_action, their_action)
        self.round_num = 0
        self.opponent_history = {}  # agent_id -> list of actions observed
        self.cooperation_count = 0
        self.defection_count = 0
        self.total_actions = 0
        self.generation = 0
        # Parameters
        self.initial_reputation = 0.5
        self.reputation_decay = 0.99
        self.forgiveness_factor = 0.8
        self.mistrust_threshold = 0.3
        self.cooperation_bias = 0.1

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        if opponent is None:
            return True

        # Update round number based on number of decisions made
        self.round_num += 1

        # Get opponent reputation if known
        opp_rep = self.reputation.get(opponent, self.initial_reputation)
        my_rep = self.my_reputation

        # If we have interaction history with this opponent, use it
        history = self.interactions.get(opponent, [])
        if history:
            # Last interaction with this opponent
            last_my, last_their = history[-1]
            # If they defected last time and we cooperated, be cautious
            if last_their == 'defect' and last_my == 'cooperate':
                # Probability to defect based on their reputation
                if opp_rep < 0.5:
                    return False
                else:
                    # If they have decent reputation, forgive but with some chance
                    return random.random() > self.forgiveness_factor * (1 - opp_rep)
            # If we both defected, try to re-engage
            elif last_their == 'defect' and last_my == 'defect':
                # Cooperate if they have decent reputation, else defect
                return opp_rep > self.mistrust_threshold
            # If we both cooperated, continue cooperating
            elif last_their == 'cooperate' and last_my == 'cooperate':
                return True
            # If we defected and they cooperated, they are forgiving - cooperate back
            else:
                return True

        # No history with this opponent - use reputation
        # If opponent reputation is good, cooperate; if bad, defect
        if opp_rep > 0.6:
            return True
        elif opp_rep < 0.3:
            return False
        else:
            # Middle ground: cooperate with probability based on reputation
            return random.random() < opp_rep

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents based on actions
        # Cooperation is good, defection is bad

        # Update donor reputation
        if donor_id != self.agent_id:
            self._update_reputation(donor_id, donor_action, 'donor')
        # Update recipient reputation (recipient chose action too)
        if recipient_id != self.agent_id and recipient_id != donor_id:
            self._update_reputation(recipient_id, recipient_action, 'recipient')

        # Self-observation: update my own reputation based on my action
        if donor_id == self.agent_id:
            self._update_self_reputation(donor_action)
            # Record interaction if I was donor
            if recipient_id != self.agent_id:
                self._record_interaction(recipient_id, donor_action, recipient_action)
        if recipient_id == self.agent_id:
            self._update_self_reputation(recipient_action)
            # Record interaction if I was recipient
            if donor_id != self.agent_id:
                # Note: donor and recipient both act simultaneously, but we record
                # with donor as "other" for simplicity
                self._record_interaction(donor_id, recipient_action, donor_action)

        # Also track observed actions of others (for opponent modeling)
        if donor_id != self.agent_id:
            self._track_opponent_action(donor_id, donor_action)
        if recipient_id != self.agent_id and recipient_id != donor_id:
            self._track_opponent_action(recipient_id, recipient_action)

        # Occasionally decay reputation to prevent runaway
        if self.round_num % 50 == 0:
            for key in list(self.reputation.keys()):
                self.reputation[key] = self.reputation[key] * self.reputation_decay + 0.05
            self.my_reputation = self.my_reputation * self.reputation_decay + 0.05

    def _update_reputation(self, agent_id: int, action: str, role: str) -> None:
        current = self.reputation.get(agent_id, self.initial_reputation)
        if action == 'cooperate':
            # Cooperation increases reputation, more if they are donor
            if role == 'donor':
                current += 0.1
            else:
                current += 0.05
        else:
            # Defection decreases reputation
            if role == 'donor':
                current -= 0.2
            else:
                current -= 0.1
        # Clamp between 0 and 1
        self.reputation[agent_id] = max(0.0, min(1.0, current))

    def _update_self_reputation(self, action: str) -> None:
        if action == 'cooperate':
            self.my_reputation += 0.05
        else:
            self.my_reputation -= 0.15
        self.my_reputation = max(0.0, min(1.0, self.my_reputation))

    def _record_interaction(self, other_id: int, my_action: str, their_action: str) -> None:
        if other_id not in self.interactions:
            self.interactions[other_id] = []
        self.interactions[other_id].append((my_action, their_action))
        # Keep last 20 interactions per opponent to avoid memory bloat
        if len(self.interactions[other_id]) > 20:
            self.interactions[other_id] = self.interactions[other_id][-20:]

    def _track_opponent_action(self, agent_id: int, action: str) -> None:
        if agent_id not in self.opponent_history:
            self.opponent_history[agent_id] = []
        self.opponent_history[agent_id].append(action)
        # Keep last 50 observations
        if len(self.opponent_history[agent_id]) > 50:
            self.opponent_history[agent_id] = self.opponent_history[agent_id][-50:]

