        self.coop_count = {}
        self.defect_count = {}
        # Track partnership history: (self_id, other_id) -> list of (my_action, their_action)
        self.history = {}
        # Generational reset flag
        self.gen = 0
        # Recent interactions for adaptive behavior
        self.recent = []

