        opponent = self._ctx_opponent_id
        # If no info, cooperate initially
        if opponent not in self.reputation:
            return True
        # Use reputation-based threshold with a bit of randomness to avoid exploitation
        rep = self.reputation.get(opponent, 0.0)
        # If opponent has decent reputation, cooperate; otherwise defect
        threshold = 0.2
        if rep > threshold:
            return True
        else:
            # Occasionally cooperate to forgive, but mostly defect
            return random.random() < 0.1

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both participants
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
