        # Reputation scores: agent_id -> score (higher = more cooperative)
        self.reputation = {}
        # Track cooperation/defection counts for self and others
        self.coop_count = {}
        self.defect_count = {}
        # Track partnership history: (self_id, other_id) -> list of (my_action, their_action)
        self.history = {}
        # Generational reset flag
        self.gen = 0
        # Recent interactions for adaptive behavior
        self.recent = []

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # If no info, cooperate initially
        if opponent not in self.reputation:
            return True
        # Use reputation-based threshold with a bit of randomness to avoid exploitation
        rep = self.reputation.get(opponent, 0.0)
        # If opponent has decent reputation, cooperate; otherwise defect
        threshold = 0.2
        if rep > threshold:
            return True
        else:
            # Occasionally cooperate to forgive, but mostly defect
            return random.random() < 0.1

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both participants
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'cooperate':
                self.reputation[pid] = self.reputation.get(pid, 0.5) + 0.1
                self.coop_count[pid] = self.coop_count.get(pid, 0) + 1
            else:
                self.reputation[pid] = self.reputation.get(pid, 0.5) - 0.15
                self.defect_count[pid] = self.defect_count.get(pid, 0) + 1
            # Clamp reputation
            self.reputation[pid] = max(0.0, min(1.0, self.reputation[pid]))

