            my_action = donor_action if donor_id == self.agent_id else recipient_action
            their_action = recipient_action if donor_id == self.agent_id else donor_action
            key = (self.agent_id, other)
            if key not in self.history:
                self.history[key] = []
            self.history[key].append((my_action, their_action))
            # Keep recent list for adaptivity
            self.recent.append((other, my_action, their_action))
