        self._ctx_opponent_id = None

        # Reputation scores: agent_id -> score (higher = more cooperative)
        self.reputation = {}
        # Cooperation history: agent_id -> list of booleans
        self.coop_history = {}
        # Memory of last own action and opponent
        self.last_opponent = None
        self.last_action = None

        # Parameters
        self.initial_rep = 1.0
        self.alpha = 0.3  # weight for opponent's reputation
        self.beta = 0.5   # weight for opponent's recent cooperation
        self.gamma = 0.2  # weight for own recent cooperation tendency
        self.forgiveness = 0.3

    def _get_rep(self, agent_id: int) -> float:
        return self.reputation.get(agent_id, self.initial_rep)

    def _set_rep(self, agent_id: int, score: float) -> None:
        # Clamp to avoid extreme values
        self.reputation[agent_id] = max(-1.0, min(1.0, score))

    def _update_rep_from_action(self, agent_id: int, action: str) -> None:
        old = self._get_rep(agent_id)
        # Cooperative actions increase, defective decrease
        if action == 'cooperate':
            new = old + 0.1
        else:
            new = old - 0.2
        self._set_rep(agent_id, new)

    def _recent_coop_rate(self, agent_id: int, window: int = 5) -> float:
        hist = self.coop_history.get(agent_id, [])
        if not hist:
            return 0.5
        recent = hist[-window:]
        return sum(recent) / len(recent)

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True  # fallback

        # Gather signals
        rep_opp = self._get_rep(opp)
        coop_rate = self._recent_coop_rate(opp)

        # Own recent behavior
        own_hist = self.coop_history.get(self.agent_id, [])
        own_rate = sum(own_hist[-5:]) / len(own_hist[-5:]) if own_hist else 0.5

        # Compute probability of cooperation
        p = 0.5 + self.alpha * rep_opp + self.beta * (coop_rate - 0.5) + self.gamma * (own_rate - 0.5)
        p = max(0.0, min(1.0, p))

        # Some stochasticity to avoid predictability
        return random.random() < p

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for both participants
        self._update_rep_from_action(donor_id, donor_action)
        self._update_rep_from_action(recipient_id, recipient_action)

        # Track cooperation history
        for aid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if aid not in self.coop_history:
                self.coop_history[aid] = []
            self.coop_history[aid].append(action == 'cooperate')

        # Self-judgment: if I was involved, adjust my own trust slightly
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # If I cooperated and opponent defected, punish opponent
            if donor_id == self.agent_id and donor_action == 'cooperate' and recipient_action == 'defect':
                self._set_rep(recipient_id, self._get_rep(recipient_id) - 0.2)
            if recipient_id == self.agent_id and recipient_action == 'cooperate' and donor_action == 'defect':
                self._set_rep(donor_id, self._get_rep(donor_id) - 0.2)
            # If I was betrayed, forgive a bit over time
            elif donor_id == self.agent_id and donor_action == 'defect' and recipient_action == 'cooperate':
                self._set_rep(recipient_id, self._get_rep(recipient_id) + self.forgiveness * 0.1)
        else:
            # Third-party: if someone defects against a cooperator, reduce their rep more
            if donor_action == 'defect' and recipient_action == 'cooperate':
                self._set_rep(donor_id, self._get_rep(donor_id) - 0.1)

