class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation: dict mapping agent_id -> reputation score in [0, 1]
        self.reputation = {}
        # Interaction counts: dict mapping agent_id -> (coop_count, defect_count)
        self.interaction_counts = {}
        # Generosity parameter (0..1)
        self.generosity = 0.7
        # Recent own actions to track patterns
        self.recent_actions = []
        # opponent cooperation probability estimates
        self.opponent_coop_prob = {}
        # Small epsilon for probability updates
        self.eps = 0.05

    def _update_reputation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str):
        # Update reputation based on actions: cooperate increases reputation, defect decreases
        # Use a simple moving average
        if donor_id != self.agent_id:
            if donor_id not in self.reputation:
                self.reputation[donor_id] = 0.5
            if donor_action == 'cooperate':
                self.reputation[donor_id] += 0.1 * (1.0 - self.reputation[donor_id])
            else:
                self.reputation[donor_id] += 0.1 * (0.0 - self.reputation[donor_id])
        if recipient_id != self.agent_id:
            if recipient_id not in self.reputation:
                self.reputation[recipient_id] = 0.5
            # For recipient, we also consider their action (they chose too)
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] += 0.1 * (1.0 - self.reputation[recipient_id])
            else:
                self.reputation[recipient_id] += 0.1 * (0.0 - self.reputation[recipient_id])

    def _update_interaction(self, agent_id: int, action: str):
        if agent_id not in self.interaction_counts:
            self.interaction_counts[agent_id] = [0, 0]  # [coops, defects]
        if action == 'cooperate':
            self.interaction_counts[agent_id][0] += 1
        else:
            self.interaction_counts[agent_id][1] += 1

    def _update_opponent_prob(self, opponent_id: int, action: str):
        if opponent_id not in self.opponent_coop_prob:
            self.opponent_coop_prob[opponent_id] = 0.5
        # Update with a learning rate
        prob = self.opponent_coop_prob[opponent_id]
        if action == 'cooperate':
            self.opponent_coop_prob[opponent_id] = prob + self.eps * (1.0 - prob)
        else:
            self.opponent_coop_prob[opponent_id] = prob + self.eps * (0.0 - prob)

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            # Update reputation for all observed agents (except self)
            self._update_reputation(donor_id, donor_action, recipient_id, recipient_action)
            # If we are involved, update interaction counts and opponent probabilities
            if donor_id == self.agent_id:
                # We were donor
                self.recent_actions.append(donor_action)
                if len(self.recent_actions) > 20:
                    self.recent_actions.pop(0)
                self._update_interaction(recipient_id, donor_action)
                self._update_opponent_prob(recipient_id, recipient_action)
            elif recipient_id == self.agent_id:
                # We were recipient
                self.recent_actions.append(recipient_action)
                if len(self.recent_actions) > 20:
                    self.recent_actions.pop(0)
                self._update_interaction(donor_id, recipient_action)
                self._update_opponent_prob(donor_id, donor_action)
            else:
                # Third-party observation: update opponent probabilities for both if we care
                # We don't have direct interaction, but we can update their reputation already
                pass
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent_id = self._ctx_opponent_id
            # If we have no info on opponent, cooperate with generosity probability
            if opponent_id not in self.reputation:
                return random.random() < self.generosity
            # Get opponent reputation
            opp_rep = self.reputation.get(opponent_id, 0.5)
            # Get opponent cooperation probability estimate if we have interacted
            opp_coop_prob = self.opponent_coop_prob.get(opponent_id, 0.5)
            # Also consider our own recent behavior: if we've been defecting a lot, maybe cooperate more
            recent_defect_rate = 0.0
            if len(self.recent_actions) > 0:
                recent_defect_rate = self.recent_actions.count('defect') / len(self.recent_actions)
            # Strategy: cooperate if opponent is reputable and likely to cooperate
            # Also add some generosity and tilt based on our own recent defection rate
            coop_score = 0.5 * opp_rep + 0.3 * opp_coop_prob + 0.2 * (1.0 - recent_defect_rate)
            # Slight randomness to avoid being too predictable
            threshold = 0.45 + 0.1 * self.generosity
            # If opponent has a very low reputation, likely defect
            if opp_rep < 0.2:
                return False
            return coop_score >= threshold
        except Exception:
            # Fallback: cooperate with some probability
            return random.random() < self.generosity

