        self.cooperation_counts = {}
        self.defection_counts = {}
        self.last_opponent = None
        self.my_last_action = None
        self.opponent_last_action = None
        self.generosity = 0.5
        self.trust = 0.5
        self.revenge_threshold = 0.3
        self.defection_penalty = 0.1
        self.cooperation_reward = 0.05
        self.third_party_impact = 0.02

    def decide(self) -> bool:
        self.round += 1
        opp = self._ctx_opponent_id
        self.last_opponent = opp

        # Track opponent's past behavior
        coop = self.cooperation_counts.get(opp, 0)
        defects = self.defection_counts.get(opp, 0)
        total = coop + defects

        # If no history, cooperate initially
        if total == 0:
            self.my_last_action = True
            return True

        # Compute opponent's cooperation rate
        coop_rate = coop / total

        # Adaptive threshold based on trust and generosity
        threshold = self.trust * self.generosity + 0.5 * (1 - self.generosity)

        # If opponent has been cooperative, cooperate; if defected recently, punish
        if coop_rate >= threshold:
            decision = True
        else:
            # Check if opponent defected in last encounter
            if self.opponent_last_action is not None and self.opponent_last_action == 'defect':
                # Punish with some probability to avoid being too predictable
                decision = random.random() > self.revenge_threshold
            else:
                decision = coop_rate >= 0.5

        self.my_last_action = decision
        return decision

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update opponent histories based on their actions in any observed interaction
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue  # Skip self, but we could use for self-reflection if needed
            if action == 'cooperate':
                self.cooperation_counts[agent_id] = self.cooperation_counts.get(agent_id, 0) + 1
            else:
                self.defection_counts[agent_id] = self.defection_counts.get(agent_id, 0) + 1

        # If this involves our last opponent, record their last action
        if self.last_opponent is not None:
            if donor_id == self.last_opponent:
                self.opponent_last_action = donor_action
            elif recipient_id == self.last_opponent:
                self.opponent_last_action = recipient_action

        # Update trust based on third-party observations
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # If both cooperate, trust increases slightly; if any defects, trust decreases
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.trust = min(1.0, self.trust + self.third_party_impact)
            elif donor_action == 'defect' or recipient_action == 'defect':
                self.trust = max(0.0, self.trust - self.third_party_impact * 2)

        # If we are the donor or recipient, update based on outcome
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            my_action = donor_action if donor_id == self.agent_id else recipient_action

            # If other defected, increase revenge threshold (more likely to punish)
            if other_action == 'defect':
                self.revenge_threshold = min(1.0, self.revenge_threshold + self.defection_penalty)
            else:
                self.revenge_threshold = max(0.0, self.revenge_threshold - self.cooperation_reward)

            # Adjust generosity based on outcomes
            if my_action == 'cooperate' and other_action == 'cooperate':
                self.generosity = min(1.0, self.generosity + 0.01)
            elif my_action == 'defect' and other_action == 'defect':
                self.generosity = max(0.0, self.generosity - 0.01)

        # Occasionally reset revenge threshold if too high to avoid eternal grudges
        if self.revenge_threshold > 0.8:
            self.revenge_threshold = 0.5

