class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.my_reputation = {}
        self.opponent_reputation = {}
        self.cooperation_score = {}
        self.defection_score = {}
        self.total_actions = {}
        self.personal_history = {}
        self.generation = 0
        self.round_in_generation = 0
        self.total_rounds = 0
        self.last_opponent = None
        self.my_last_action = None
        self.opp_last_action = None
        self.trust = {}
        self.reciprocity = {}
        self.forgiveness = {}
        self.recent_actions = {}
        self.self_image = 0.5
        self.alpha = 0.1
        self.beta = 0.05
        self.cooperation_bias = 0.0
        self.defection_bias = 0.0
        self.total_observations = 0
        self.personal_observations = 0
        self.third_party_observations = 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.last_opponent = opp
        # Initialize if unknown
        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.cooperation_score:
            self.cooperation_score[opp] = 0
        if opp not in self.defection_score:
            self.defection_score[opp] = 0
        if opp not in self.total_actions:
            self.total_actions[opp] = 0
        if opp not in self.trust:
            self.trust[opp] = 0.5
        if opp not in self.reciprocity:
            self.reciprocity[opp] = 0.5
        if opp not in self.forgiveness:
            self.forgiveness[opp] = 0.5
        if opp not in self.recent_actions:
            self.recent_actions[opp] = []
        if opp not in self.personal_history:
            self.personal_history[opp] = []

        # Compute probability of cooperation based on reputation and trust
        rep = self.reputation[opp]
        trust = self.trust[opp]
        # Combine reputation and trust with weight
        base_prob = 0.5 + 0.5 * (rep - 0.5) * 0.7 + 0.5 * (trust - 0.5) * 0.3
        # Adjust based on my own reputation (self-image)
        self_rep = self.self_image
        base_prob += (self_rep - 0.5) * 0.2

        # Reciprocity: if last interaction with this opponent, adjust
        if len(self.personal_history[opp]) > 0:
            last_my, last_opp = self.personal_history[opp][-1]
            if last_my and last_opp:  # both cooperated
                base_prob += 0.1
            elif last_my and not last_opp:  # I cooperated, they defected
                base_prob -= 0.2
            elif not last_my and last_opp:  # I defected, they cooperated
                base_prob += 0.05
            else:  # both defected
                base_prob -= 0.05

        # Forgiveness: if opponent defected recently but then cooperated, increase
        if len(self.recent_actions[opp]) >= 2:
            if self.recent_actions[opp][-1] and not self.recent_actions[opp][-2]:
                base_prob += 0.1
            elif not self.recent_actions[opp][-1] and self.recent_actions[opp][-2]:
                base_prob -= 0.1

        # Add small random noise to avoid deterministic traps
        noise = random.uniform(-0.05, 0.05)
        prob = min(1.0, max(0.0, base_prob + noise))

        # Decide
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.total_observations += 1
        is_self = (donor_id == self.agent_id or recipient_id == self.agent_id)
        if is_self:
            self.personal_observations += 1
        else:
            self.third_party_observations += 1

        # Update generation and round based on total observations (approx)
        # Not critical for strategy, but track rounds
        if self.total_observations % 15 == 0:
            self.round_in_generation += 1
            if self.round_in_generation > 30:
                self.round_in_generation = 1
                self.generation += 1
                self.total_rounds = 0

        # Update reputation for both agents
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Update personal history if I am involved
        if donor_id == self.agent_id:
            my_action = donor_action == 'cooperate'
            opp_action = recipient_action == 'cooperate'
            opp = recipient_id
            self._update_personal(opp, my_action, opp_action)
        elif recipient_id == self.agent_id:
            my_action = recipient_action == 'cooperate'
            opp_action = donor_action == 'cooperate'
            opp = donor_id
            self._update_personal(opp, my_action, opp_action)

        # Update trust and reciprocity for third-party observations
        if not is_self:
            # If donor cooperates with recipient, increase trust in donor
            if donor_action == 'cooperate':
                self._update_trust(donor_id, +0.02)
                self._update_reciprocity(donor_id, +0.01)
            else:
                self._update_trust(donor_id, -0.03)
                self._update_reciprocity(donor_id, -0.02)
            if recipient_action == 'cooperate':
                self._update_trust(recipient_id, +0.02)
                self._update_reciprocity(recipient_id, +0.01)
            else:
                self._update_trust(recipient_id, -0.03)
                self._update_reciprocity(recipient_id, -0.02)

        # Update self-image based on my own actions
        if donor_id == self.agent_id:
            self._update_self_image(donor_action == 'cooperate')
        if recipient_id == self.agent_id:
            self._update_self_image(recipient_action == 'cooperate')

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
            self.cooperation_score[agent_id] = 0
            self.defection_score[agent_id] = 0
            self.total_actions[agent_id] = 0
        if action == 'cooperate':
            self.cooperation_score[agent_id] += 1
        else:
            self.defection_score[agent_id] += 1
        self.total_actions[agent_id] += 1
        coop = self.cooperation_score[agent_id]
        total = self.total_actions[agent_id]
        # Update reputation as a weighted average, recent more important
        new_rep = 0.5 + 0.5 * (coop / total - 0.5) * 2  # maps to 0..1
        # Smooth update
        self.reputation[agent_id] = 0.9 * self.reputation[agent_id] + 0.1 * new_rep

    def _update_personal(self, opp: int, my_action: bool, opp_action: bool) -> None:
        if opp not in self.personal_history:
            self.personal_history[opp] = []
        self.personal_history[opp].append((my_action, opp_action))
        if len(self.personal_history[opp]) > 10:
            self.personal_history[opp].pop(0)
        if opp not in self.recent_actions:
            self.recent_actions[opp] = []
        self.recent_actions[opp].append(opp_action)
        if len(self.recent_actions[opp]) > 5:
            self.recent_actions[opp].pop(0)

        # Update trust based on outcome
        if my_action and opp_action:
            self._update_trust(opp, +0.05)
            self._update_reciprocity(opp, +0.03)
        elif my_action and not opp_action:
            self._update_trust(opp, -0.1)
            self._update_reciprocity(opp, -0.1)
        elif not my_action and opp_action:
            self._update_trust(opp, +0.02)
            self._update_reciprocity(opp, -0.02)
        else:
            self._update_trust(opp, -0.02)
            self._update_reciprocity(opp, +0.02)

    def _update_trust(self, agent_id: int, delta: float) -> None:
        if agent_id not in self.trust:
            self.trust[agent_id] = 0.5
        self.trust[agent_id] += delta
        self.trust[agent_id] = min(1.0, max(0.0, self.trust[agent_id]))

    def _update_reciprocity(self, agent_id: int, delta: float) -> None:
        if agent_id not in self.reciprocity:
            self.reciprocity[agent_id] = 0.5
        self.reciprocity[agent_id] += delta
        self.reciprocity[agent_id] = min(1.0, max(0.0, self.reciprocity[agent_id]))

    def _update_self_image(self, cooperated: bool) -> None:
        if cooperated:
            self.self_image += self.alpha * (1.0 - self.self_image)
        else:
            self.self_image -= self.beta * self.self_image
        self.self_image = min(1.0, max(0.0, self.self_image))

