        opp = self._ctx_opponent_id
        self.last_opponent = opp
        # Initialize if unknown
        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.cooperation_score:
            self.cooperation_score[opp] = 0
        if opp not in self.defection_score:
