        if opp not in self.total_actions:
            self.total_actions[opp] = 0
        if opp not in self.trust:
            self.trust[opp] = 0.5
        if opp not in self.reciprocity:
            self.reciprocity[opp] = 0.5
        if opp not in self.forgiveness:
            self.forgiveness[opp] = 0.5
        if opp not in self.recent_actions:
            self.recent_actions[opp] = []
        if opp not in self.personal_history:
            self.personal_history[opp] = []

        # Compute probability of cooperation based on reputation and trust
        rep = self.reputation[opp]
        trust = self.trust[opp]
        # Combine reputation and trust with weight
        base_prob = 0.5 + 0.5 * (rep - 0.5) * 0.7 + 0.5 * (trust - 0.5) * 0.3
        # Adjust based on my own reputation (self-image)
        self_rep = self.self_image
        base_prob += (self_rep - 0.5) * 0.2

        # Reciprocity: if last interaction with this opponent, adjust
        if len(self.personal_history[opp]) > 0:
            last_my, last_opp = self.personal_history[opp][-1]
            if last_my and last_opp:  # both cooperated
                base_prob += 0.1
            elif last_my and not last_opp:  # I cooperated, they defected
                base_prob -= 0.2
            elif not last_my and last_opp:  # I defected, they cooperated
                base_prob += 0.05
            else:  # both defected
                base_prob -= 0.05

        # Forgiveness: if opponent defected recently but then cooperated, increase
        if len(self.recent_actions[opp]) >= 2:
            if self.recent_actions[opp][-1] and not self.recent_actions[opp][-2]:
                base_prob += 0.1
            elif not self.recent_actions[opp][-1] and self.recent_actions[opp][-2]:
                base_prob -= 0.1

        # Add small random noise to avoid deterministic traps
        noise = random.uniform(-0.05, 0.05)
        prob = min(1.0, max(0.0, base_prob + noise))

        # Decide
        return random.random() < prob

