        if opponent_id not in self.opponent_coop_prob:
            self.opponent_coop_prob[opponent_id] = 0.5
        prob = self.opponent_coop_prob[opponent_id]
        if action == 'cooperate':
            self.opponent_coop_prob[opponent_id] = prob + self.eps * (1.0 - prob)
        else:
            self.opponent_coop_prob[opponent_id] = prob + self.eps * (0.0 - prob)

