        # Simple deterministic strategy with some randomness if needed
        # Start cooperative, then adapt based on trust
        if self.opponent_id is None:
            return True  # no opponent? should not happen
        # Get trust for this opponent
        trust = self.trust_scores.get(self.opponent_id, self.initial_trust)
        # If we have history, use a tit-for-tat style with forgiveness
        if self.opponent_id in self.own_record:
            my_actions, their_actions = zip(*self.own_record[self.opponent_id]) if self.own_record[self.opponent_id] else ([], [])
            if their_actions:
                last_their = their_actions[-1]
                # Tit-for-tat but with some forgiveness if trust is high
                if last_their == 'defect':
                    # Defect if they defected, but occasionally forgive if trust high
                    if trust > 0.7 and random.random() < 0.1:
                        return True
                    else:
                        return False
                else:
                    return True
        # No history: cooperate if trust is high, else random
        if trust > 0.5:
            return True
        else:
            return random.random() < trust  # probabilistic based on trust

