class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.opponent_history = {}
        self.own_record = {}  # opponent_id -> list of (my_action, their_action)
        self.scores = {}  # opponent_id -> total score against them
        self.generation = 0
        self.round_in_generation = 0
        self.defection_rate = 0.0
        self.cooperation_rate = 1.0
        self.last_opponent = None
        self.last_my_action = None
        self.last_their_action = None
        self.total_rounds = 0
        self.my_recent_actions = []  # last 30 actions
        self.their_recent_actions = []  # last 30 actions (for current opponent)
        self.trust_scores = {}  # opponent_id -> trust value 0..1
        self.trust_decay = 0.95
        self.initial_trust = 0.5
        self.reputation = {}  # observed behavior of others, opponent_id -> [coop, defect] counts
        self.observed_pairs = []  # keep last few observations for global patterns
        self.recent_observations = []  # (donor, action, recipient, action) last 30

    def decide(self) -> bool:
        # Simple deterministic strategy with some randomness if needed
        # Start cooperative, then adapt based on trust
        if self.opponent_id is None:
            return True  # no opponent? should not happen
        # Get trust for this opponent
        trust = self.trust_scores.get(self.opponent_id, self.initial_trust)
        # If we have history, use a tit-for-tat style with forgiveness
        if self.opponent_id in self.own_record:
            my_actions, their_actions = zip(*self.own_record[self.opponent_id]) if self.own_record[self.opponent_id] else ([], [])
            if their_actions:
                last_their = their_actions[-1]
                # Tit-for-tat but with some forgiveness if trust is high
                if last_their == 'defect':
                    # Defect if they defected, but occasionally forgive if trust high
                    if trust > 0.7 and random.random() < 0.1:
                        return True
                    else:
                        return False
                else:
                    return True
        # No history: cooperate if trust is high, else random
        if trust > 0.5:
            return True
        else:
            return random.random() < trust  # probabilistic based on trust

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update own records if we are involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent and my action
            if donor_id == self.agent_id:
                my_action = donor_action
                their_action = recipient_action
                opponent = recipient_id
            else:
                my_action = recipient_action
                their_action = donor_action
                opponent = donor_id
            # Store in own_record
            if opponent not in self.own_record:
                self.own_record[opponent] = []
                self.trust_scores[opponent] = self.initial_trust
                self.scores[opponent] = 0.0
            self.own_record[opponent].append((my_action, their_action))
            # Update score: cooperate=1, defect=0? Or use payoff matrix? We'll use simple: cooperate gives 1, defect gives 0, but if both defect 0, if both cooperate 1 each? Actually we don't have payoff, just track cooperation rate
            # For trust: if they cooperate, increase trust; if defect, decrease
            if their_action == 'cooperate':
                self.trust_scores[opponent] = min(1.0, self.trust_scores[opponent] * self.trust_decay + 0.1)
            else:
                self.trust_scores[opponent] = max(0.0, self.trust_scores[opponent] * self.trust_decay - 0.1)
            # Update recent actions
            self.my_recent_actions.append(my_action)
            if len(self.my_recent_actions) > 30:
                self.my_recent_actions.pop(0)
            self.their_recent_actions.append(their_action)
            if len(self.their_recent_actions) > 30:
                self.their_recent_actions.pop(0)
        else:
            # Third-party observation: update reputation of others
            if donor_id not in self.reputation:
                self.reputation[donor_id] = [0, 0]  # coop, defect
            if donor_action == 'cooperate':
                self.reputation[donor_id][0] += 1
            else:
                self.reputation[donor_id][1] += 1
            if recipient_id not in self.reputation:
                self.reputation[recipient_id] = [0, 0]
            if recipient_action == 'cooperate':
                self.reputation[recipient_id][0] += 1
            else:
                self.reputation[recipient_id][1] += 1
            # Store recent observation
            self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))
