        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        # Default: cooperate if no info
        if opponent not in self.trust:
            return True
        trust_score = self.trust.get(opponent, 0.0)
        # Stochastic threshold based on trust
        threshold = 0.55 + 0.2 * math.tanh(trust_score / 5.0)
        return random.random() < threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update counts for self actions
        if donor_id == self.agent_id:
            self.coop_count += (donor_action == 'cooperate')
            self.defect_count += (donor_action == 'defect')
            self.last_actions[recipient_id] = donor_action
        if recipient_id == self.agent_id:
            self.last_actions[donor_id] = recipient_action

        # Update reputation for both participants if we are third party
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Reputation: how much they cooperate relative to defections
            for pid, act in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                coop = (act == 'cooperate')
                self.reputation[pid] = self.reputation.get(pid, 0.0) + (1.0 if coop else -0.5)

        # Update trust for self interactions
        if donor_id == self.agent_id:
            # What recipient did to us
            other = recipient_id
            if other not in self.trust:
                self.trust[other] = 0.0
            # If they cooperated with us, increase trust; if defected, decrease
            if recipient_action == 'cooperate':
                self.trust[other] += 0.5
            else:
                self.trust[other] -= 1.0
            # Also consider our action? Not needed for trust of them.
        if recipient_id == self.agent_id:
            other = donor_id
            if other not in self.trust:
                self.trust[other] = 0.0
            if donor_action == 'cooperate':
                self.trust[other] += 0.5
            else:
                self.trust[other] -= 1.0

        # Update round tracking? Not needed.
        # Keep trust bounded to avoid extreme values
        for pid in self.trust:
            self.trust[pid] = max(-10.0, min(10.0, self.trust[pid]))

        # Occasionally decay trust to allow forgiveness
        if self.round % 10 == 0:
            for pid in list(self.trust.keys()):
                self.trust[pid] *= 0.95
        self.round += 1

